{"explanation":"Arrange four congruent right triangles inside a large square in two ways. The triangles have the same total area in both arrangements, so the leftover regions must also have equal area: one arrangement leaves a square of area \(c^2\), and the other leaves two squares with total area \(a^2+b^2\). Thus \(c^2=a^2+b^2\).","manimCode":"const a = 2.4, b = 1.8, c = Math.sqrt(a*a + b*b);
const s = a + b;
const sc = 0.72;
const ox = -2.0, oy = -1.55;
const P = (x,y) => [ox + sc*x, oy + sc*y, 0];
const title = new Text({text:'Four-triangle rearrangement', color:WHITE, fontSize:30});
title.moveTo([0,3.25,0]);
const caption = new Text({text:'Same outer square • same four triangles • equal leftover area', color:GRAY, fontSize:20});
caption.moveTo([0,-3.05,0]);

// Left: four right triangles leave a central square of side c.
const outer1 = new Polygon({vertices:[P(0,0),P(s,0),P(s,s),P(0,s)], color:WHITE});
outer1.setFill(BLACK,0).setStrokeWidth(2);
const tri1 = [
  [[0,0],[a,0],[a,b]],
  [[s,0],[s,a],[s-b,a]],
  [[s,s],[s-a,s],[s-a,s-b]],
  [[0,s],[0,s-a],[b,s-a]]
].map(v=>{ const q=new Polygon({vertices:v.map(p=>P(p[0],p[1])),color:BLUE_C}); q.setFill(BLUE_C,0.72).setStrokeWidth(1.5); return q; });
const hole1 = new Polygon({vertices:[P(a,0),P(s,a),P(b,s),P(0,b)],color:GOLD});
hole1.setFill(GOLD,0.25).setStrokeWidth(2);
const labC = new Text({text:'c²',color:GOLD,fontSize:28}); labC.moveTo(P(s/2,s/2));
const tag1 = new Text({text:'Arrangement 1',color:WHITE,fontSize:22}); tag1.moveTo([-2.0,2.15,0]);

// Right: same square, four triangles leave a-by-a and b-by-b corner squares.
const ox2 = 2.0;
const Q = (x,y) => [ox2 + sc*x, oy + sc*y, 0];
const outer2 = new Polygon({vertices:[Q(0,0),Q(s,0),Q(s,s),Q(0,s)],color:WHITE});
outer2.setFill(BLACK,0).setStrokeWidth(2);
const tri2 = [
  [[0,0],[a,0],[0,b]],
  [[a,0],[s,0],[s,a]],
  [[s,a],[s,s],[b,s]],
  [[b,s],[0,s],[0,b]]
].map(v=>{ const q=new Polygon({vertices:v.map(p=>Q(p[0],p[1])),color:BLUE_C}); q.setFill(BLUE_C,0.72).setStrokeWidth(1.5); return q; });
const sqA = new Polygon({vertices:[Q(a,0),Q(s,0),Q(s,a),Q(a,a)],color:GREEN_C});
sqA.setFill(GREEN_C,0.3).setStrokeWidth(2);
const sqB = new Polygon({vertices:[Q(0,b),Q(b,b),Q(b,s),Q(0,s)],color:ORANGE});
sqB.setFill(ORANGE,0.3).setStrokeWidth(2);
const labA = new Text({text:'a²',color:GREEN_C,fontSize:24}); labA.moveTo(Q((a+s)/2,a/2));
const labB = new Text({text:'b²',color:ORANGE,fontSize:24}); labB.moveTo(Q(b/2,(b+s)/2));
const tag2 = new Text({text:'Arrangement 2',color:WHITE,fontSize:22}); tag2.moveTo([2.0,2.15,0]);
const eq = new MathTex({latex:'c^2 = a^2 + b^2'}); await eq.waitForRender(); eq.moveTo([0,-2.45,0]);

await scene.play(new Write(title));
await scene.play(new AnimationGroup([new Create(outer1),new Create(outer2),new Write(tag1),new Write(tag2)]));
await scene.play(new AnimationGroup([...tri1.map(t=>new DrawBorderThenFill(t)),...tri2.map(t=>new DrawBorderThenFill(t))]));
await scene.play(new AnimationGroup([new Create(hole1),new Write(labC),new Create(sqA),new Create(sqB),new Write(labA),new Write(labB)]));
await scene.play(new Write(eq));
const controls = new Controls(scene,{position:'bottom-right',width:210});
controls.addButton({label:'Highlight equal areas',onClick:()=>{hole1.setStrokeWidth(4);sqA.setStrokeWidth(4);sqB.setStrokeWidth(4);}});
await scene.wait(999999);"}

